/** A search input with a magnifier. `value` fires on every keystroke with the new text. */
import { type JSX } from "solid-js";
import { Box, Input } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { cn } from "../utils";

export type SearchFieldProps = {
  value: string;
  placeholder?: string;
  label: string;
  class?: string;
  onValue?: (value: string) => void;
};

export function SearchField({ value, placeholder, label, class: className, onValue }: SearchFieldProps) {
  return (
    <Box class={cn("relative min-w-44 flex-1", className)} role="search">
      <LucideIcon name="search" size={16} class="pointer-events-none absolute top-2 left-3 text-muted-foreground" />
      <Input
        size="sm"
        type="search"
        placeholder={placeholder}
        aria-label={label}
        class="pr-3 pl-10"
        value={value}
        onInput={(event: InputEvent & { currentTarget: HTMLInputElement }) => onValue?.(event.currentTarget.value)}
      />
    </Box>
  );
}
